mapper.select:
select case when planstatus=1 then '未评估' when planstatus=2 then '评估中' when planstatus=3 then '已评估' else '未下发' end as name ,count(1) as value from TBL_RISK_ASSPLAN_RISK r left join TBL_RISK_ASSPLAN p on p.assplanid=r.assplanid left join TBL_RISK s on s.riskid=r.riskid where s.unit is not null
and p.unit=#{company}
group by planstatus order by planstatus

		 select 	a.* ,o.orgname as orgName from TBL_RISK_ASSPLAN a 
		 left join tbl_organization o on o.orgid=a.unit
		 where 1=1

            ${sql}

            and
            ${ew.sqlSegment}

select a.*,o.orgname,og.orgname as deptname from TBL_RISK_ASSPLAN a left join tbl_organization o on a.unit=o.orgid left join tbl_organization og on a.linkdeptid=og.orgid where 1=1
${sql}
and ${ew.sqlSegment}
